package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type node struct {
	k    int
	l, r *node
}

func insert(n *node, x int) (*node, bool) {
	if n == nil {
		return &node{k: x}, true
	}
	var ok bool
	if x < n.k {
		n.l, ok = insert(n.l, x)
	} else if x > n.k {
		n.r, ok = insert(n.r, x)
	}
	return n, ok
}

func del(n *node, x int) (*node, bool) {
	if n == nil {
		return nil, false
	}
	var ok bool
	if x < n.k {
		n.l, ok = del(n.l, x)
		return n, ok
	}
	if x > n.k {
		n.r, ok = del(n.r, x)
		return n, ok
	}
	if n.l == nil {
		return n.r, true
	}
	if n.r == nil {
		return n.l, true
	}
	s := n.r
	for s.l != nil {
		s = s.l
	}
	n.k = s.k
	n.r, _ = del(n.r, s.k)
	return n, true
}

func height(n *node) int {
	if n == nil {
		return 0
	}
	return 1 + max(height(n.l), height(n.r))
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	var root *node
	for sc.Scan() {
		f := strings.Fields(sc.Text())
		if len(f) == 0 {
			continue
		}
		x := 0
		if len(f) > 1 {
			x, _ = strconv.Atoi(f[1])
		}
		switch f[0] {
		case "insert":
			var ok bool
			root, ok = insert(root, x)
			if ok {
				fmt.Fprintln(w, "ok")
			} else {
				fmt.Fprintln(w, "dup")
			}
		case "contains":
			n := root
			for n != nil && n.k != x {
				if x < n.k {
					n = n.l
				} else {
					n = n.r
				}
			}
			if n != nil {
				fmt.Fprintln(w, "yes")
			} else {
				fmt.Fprintln(w, "no")
			}
		case "delete":
			var ok bool
			root, ok = del(root, x)
			if ok {
				fmt.Fprintln(w, "ok")
			} else {
				fmt.Fprintln(w, "missing")
			}
		case "inorder":
			if root == nil {
				fmt.Fprintln(w, "<empty>")
				break
			}
			var out []string
			var walk func(*node)
			walk = func(n *node) {
				if n == nil {
					return
				}
				walk(n.l)
				out = append(out, strconv.Itoa(n.k))
				walk(n.r)
			}
			walk(root)
			fmt.Fprintln(w, strings.Join(out, " "))
		case "height":
			fmt.Fprintln(w, height(root))
		case "min", "max":
			if root == nil {
				fmt.Fprintln(w, "empty")
				break
			}
			n := root
			for {
				nx := n.l
				if f[0] == "max" {
					nx = n.r
				}
				if nx == nil {
					break
				}
				n = nx
			}
			fmt.Fprintln(w, n.k)
		}
	}
}

